class Solution {
    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
        java.util.List<int[]> events = new java.util.ArrayList<>();
        for (int[] building : buildings) {
            events.add(new int[]{building[0], -building[2]});
            events.add(new int[]{building[1], building[2]});
        }
        events.sort((a, b) -> a[0] != b[0]
                ? Integer.compare(a[0], b[0])
                : Integer.compare(a[1], b[1]));

        java.util.TreeMap<Integer, Integer> active = new java.util.TreeMap<>();
        active.put(0, 1);
        java.util.List<java.util.List<Integer>> skyline = new java.util.ArrayList<>();
        int previousHeight = 0;
        int index = 0;

        while (index < events.size()) {
            int x = events.get(index)[0];
            while (index < events.size() && events.get(index)[0] == x) {
                int height = events.get(index)[1];
                if (height < 0) {
                    active.merge(-height, 1, Integer::sum);
                } else {
                    int count = active.get(height);
                    if (count == 1) {
                        active.remove(height);
                    } else {
                        active.put(height, count - 1);
                    }
                }
                index++;
            }

            int currentHeight = active.lastKey();
            if (currentHeight != previousHeight) {
                skyline.add(java.util.Arrays.asList(x, currentHeight));
                previousHeight = currentHeight;
            }
        }
        return skyline;
    }
}

class Solution {
    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
        java.util.TreeSet<Integer> coordinates = new java.util.TreeSet<>();
        for (int[] building : buildings) {
            coordinates.add(building[0]);
            coordinates.add(building[1]);
        }

        java.util.PriorityQueue<int[]> heap = new java.util.PriorityQueue<>((a, b) ->
                a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(b[1], a[1]));
        java.util.List<java.util.List<Integer>> skyline = new java.util.ArrayList<>();
        int buildingIndex = 0;
        int previousHeight = 0;

        for (int x : coordinates) {
            while (buildingIndex < buildings.length && buildings[buildingIndex][0] <= x) {
                heap.offer(new int[]{buildings[buildingIndex][2], buildings[buildingIndex][1]});
                buildingIndex++;
            }
            while (!heap.isEmpty() && heap.peek()[1] <= x) {
                heap.poll();
            }

            int currentHeight = heap.isEmpty() ? 0 : heap.peek()[0];
            if (currentHeight != previousHeight) {
                skyline.add(java.util.Arrays.asList(x, currentHeight));
                previousHeight = currentHeight;
            }
        }
        return skyline;
    }
}

class Solution {
    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
        return divide(buildings, 0, buildings.length - 1);
    }

    private java.util.List<java.util.List<Integer>> divide(int[][] buildings, int left, int right) {
        java.util.List<java.util.List<Integer>> result = new java.util.ArrayList<>();
        if (left > right) {
            return result;
        }
        if (left == right) {
            result.add(java.util.Arrays.asList(buildings[left][0], buildings[left][2]));
            result.add(java.util.Arrays.asList(buildings[left][1], 0));
            return result;
        }

        int mid = left + (right - left) / 2;
        java.util.List<java.util.List<Integer>> leftSkyline = divide(buildings, left, mid);
        java.util.List<java.util.List<Integer>> rightSkyline = divide(buildings, mid + 1, right);
        return merge(leftSkyline, rightSkyline);
    }

    private java.util.List<java.util.List<Integer>> merge(
            java.util.List<java.util.List<Integer>> left,
            java.util.List<java.util.List<Integer>> right) {
        java.util.List<java.util.List<Integer>> merged = new java.util.ArrayList<>();
        int i = 0;
        int j = 0;
        int leftHeight = 0;
        int rightHeight = 0;

        while (i < left.size() && j < right.size()) {
            int x;
            int leftX = left.get(i).get(0);
            int rightX = right.get(j).get(0);
            if (leftX < rightX) {
                x = leftX;
                leftHeight = left.get(i).get(1);
                i++;
            } else if (rightX < leftX) {
                x = rightX;
                rightHeight = right.get(j).get(1);
                j++;
            } else {
                x = leftX;
                leftHeight = left.get(i).get(1);
                rightHeight = right.get(j).get(1);
                i++;
                j++;
            }
            append(merged, x, Math.max(leftHeight, rightHeight));
        }
        while (i < left.size()) {
            append(merged, left.get(i).get(0), left.get(i).get(1));
            i++;
        }
        while (j < right.size()) {
            append(merged, right.get(j).get(0), right.get(j).get(1));
            j++;
        }
        return merged;
    }

    private void append(java.util.List<java.util.List<Integer>> skyline, int x, int height) {
        if (skyline.isEmpty() || !skyline.get(skyline.size() - 1).get(1).equals(height)) {
            skyline.add(java.util.Arrays.asList(x, height));
        }
    }
}

class Solution {
    private java.util.List<Integer> coords;
    private int[] tree;

    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
        java.util.TreeSet<Integer> edges = new java.util.TreeSet<>();
        for (int[] building : buildings) {
            edges.add(building[0]);
            edges.add(building[1]);
        }
        coords = new java.util.ArrayList<>(edges);
        java.util.Map<Integer, Integer> index = new java.util.HashMap<>();
        for (int i = 0; i < coords.size(); i++) {
            index.put(coords.get(i), i);
        }

        tree = new int[coords.size() * 4];
        for (int[] building : buildings) {
            int left = index.get(building[0]);
            int right = index.get(building[1]) - 1;
            update(1, 0, coords.size() - 2, left, right, building[2]);
        }

        java.util.List<java.util.List<Integer>> skyline = new java.util.ArrayList<>();
        int previousHeight = 0;
        for (int i = 0; i < coords.size() - 1; i++) {
            int height = query(1, 0, coords.size() - 2, i, 0);
            if (height != previousHeight) {
                skyline.add(java.util.Arrays.asList(coords.get(i), height));
                previousHeight = height;
            }
        }
        if (previousHeight != 0) {
            skyline.add(java.util.Arrays.asList(coords.get(coords.size() - 1), 0));
        }
        return skyline;
    }

    private void update(int node, int left, int right, int ql, int qr, int height) {
        if (ql > right || qr < left || ql > qr) {
            return;
        }
        if (ql <= left && right <= qr) {
            tree[node] = Math.max(tree[node], height);
            return;
        }
        int mid = left + (right - left) / 2;
        update(node * 2, left, mid, ql, qr, height);
        update(node * 2 + 1, mid + 1, right, ql, qr, height);
    }

    private int query(int node, int left, int right, int target, int carry) {
        carry = Math.max(carry, tree[node]);
        if (left == right) {
            return carry;
        }
        int mid = left + (right - left) / 2;
        if (target <= mid) {
            return query(node * 2, left, mid, target, carry);
        }
        return query(node * 2 + 1, mid + 1, right, target, carry);
    }
}
